[
  {
    "statement": "Several habitat enhancement interventions can increase invertebrate abundance on subtidal artificial structures.",
    "citations": []
  },
  {
    "statement": "Creating hole habitats larger than 50 mm showed mixed effects on invertebrate abundances.",
    "citations": [
      "3434"
    ]
  },
  {
    "statement": "One study found that creating hole habitats increased the abundance of brown crabs but not other mobile invertebrates.",
    "citations": [
      "3434"
    ]
  },
  {
    "statement": "Another study reported that creating hole habitats had mixed effects on invertebrate abundance depending on the species group.",
    "citations": [
      "3434"
    ]
  },
  {
    "statement": "Creating short flexible habitats between 1 and 50 mm had mixed effects on mobile and non-mobile invertebrate abundance.",
    "citations": [
      "3450"
    ]
  },
  {
    "statement": "The effects of short flexible habitats on invertebrate abundance varied by survey week, species group, flexible habitat length, or site.",
    "citations": [
      "3450"
    ]
  },
  {
    "statement": "Creating textured surfaces of 1 mm or less produced mixed effects on non-mobile invertebrate abundance depending on the site.",
    "citations": [
      "3449"
    ]
  },
  {
    "statement": "Creating long flexible habitats larger than 50 mm resulted in mixed effects on mobile and non-mobile invertebrate abundance.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "The effects of creating long flexible habitats on invertebrate abundance depended on the species group and survey week, or the flexible habitat's length and density.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "One study found that creating long flexible habitats decreased mussel abundance on structure surfaces.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "The long flexible habitats themselves supported higher biomass, which was mostly comprised of mussels.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "Transplanting or seeding organisms showed positive results for invertebrate abundance.",
    "citations": [
      "3471"
    ]
  },
  {
    "statement": "One study found that transplanting sea urchins reduced non-native sea mat cover on kelps.",
    "citations": [
      "3471"
    ]
  },
  {
    "statement": "Another study reported that transplanting corals increased coral cover on structure surfaces.",
    "citations": [
      "3471"
    ]
  },
  {
    "statement": "Creating groove habitats between 1 and 50 mm had mixed effects on invertebrate abundances depending on the species group.",
    "citations": [
      "3448"
    ]
  },
  {
    "statement": "Creating pit habitats between 1 and 50 mm had mixed effects on invertebrate abundances depending on the species group.",
    "citations": [
      "3455"
    ]
  },
  {
    "statement": "Different artificial reef structures and materials showed varying results for invertebrate abundance.",
    "citations": [
      "2259"
    ]
  },
  {
    "statement": "Some studies found no differences in invertebrate abundances between different reef structures and materials.",
    "citations": [
      "2259"
    ]
  },
  {
    "statement": "Other studies found specific materials like oyster shell bags recruited more oysters and ribbed mussels compared to \"ReefBall\" breakwaters.",
    "citations": [
      "2259"
    ]
  },
  {
    "statement": "Ceasing or altering maintenance activities showed limited effects on overall invertebrate abundance.",
    "citations": [
      "3447"
    ]
  },
  {
    "statement": "One study found reducing the cleaning area on a structure increased seahorse abundance on its surfaces.",
    "citations": [
      "3447"
    ]
  },
  {
    "statement": "Creating combinations of grooves and small protrusions, ridges or ledges between 1 and 50 mm had mixed effects on combined macroalgae and non-mobile invertebrate abundance.",
    "citations": [
      "3452"
    ]
  },
  {
    "statement": "The effects of creating combinations of grooves and small protrusions, ridges or ledges on abundance depended on the structure's surface orientation.",
    "citations": [
      "3452"
    ]
  }
]

[
  {
    "statement": "Creating rock pools on intertidal artificial structures provides several benefits for overall species richness.",
    "citations": []
  },
  {
    "statement": "Rock pools created on intertidal artificial structures supported higher combined macroalgae, invertebrate, and fish species diversity and richness than structure surfaces without pools.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "Rock pools supported macroalgae, mobile invertebrate, non-mobile invertebrate, and fish species that were absent from structure surfaces without pools.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "The combined macroalgae, invertebrate, and fish species richness in created pools was similar to natural rock pools in some cases.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "Creating pools, along with reducing the slope of a structure, increased the combined macroalgae, invertebrate, and fish species richness on the structure.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "Rock pools created on intertidal artificial structures were used by sea slugs, urchins, octopuses, macroalgae, invertebrates, and fishes.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "When combined with other habitat features like holes, rock pools supported macroalgae and non-mobile invertebrate species that were absent from structure surfaces without added habitat features.",
    "citations": [
      "3467"
    ]
  },
  {
    "statement": "When combined with other habitat features like holes, rock pools increased combined macroalgae and invertebrate species diversity and richness on structure surfaces.",
    "citations": [
      "3467"
    ]
  }
]

[
  {
    "statement": "Creating linear depressions (grooves) and elevations (ridges/ledges) on intertidal artificial structures has varied effects on biodiversity.",
    "citations": []
  },
  {
    "statement": "Linear depressions, such as groove habitats of 1-50mm, show mixed effects on community composition.",
    "citations": [
      "3473"
    ]
  },
  {
    "statement": "Two of three studies found that linear depressions did not alter the combined macroalgae and invertebrate community composition.",
    "citations": [
      "3473"
    ]
  },
  {
    "statement": "Grooves supported species that were absent from structure surfaces without grooves.",
    "citations": [
      "3473"
    ]
  },
  {
    "statement": "Some studies found that groove habitats increased combined macroalgae and invertebrate species richness and/or diversity.",
    "citations": [
      "3473"
    ]
  },
  {
    "statement": "Some studies found that groove habitats caused no increase in combined macroalgae and invertebrate species richness and/or diversity.",
    "citations": [
      "3473"
    ]
  },
  {
    "statement": "One study found that groove habitats had mixed effects on species richness and/or diversity depending on the site.",
    "citations": [
      "3473"
    ]
  },
  {
    "statement": "Some studies found that grooves supported higher species richness than small ridges or ledges created between them.",
    "citations": [
      "3473"
    ]
  },
  {
    "statement": "Linear elevations, such as small ridges or ledges of 1-50mm, generally showed less positive effects on biodiversity than linear depressions.",
    "citations": [
      "3464"
    ]
  },
  {
    "statement": "One study found no increase in combined macroalgae and invertebrate species richness from small ridges.",
    "citations": [
      "3464"
    ]
  },
  {
    "statement": "Studies consistently found that small ridges supported lower species richness than grooves created between them.",
    "citations": [
      "3464"
    ]
  },
  {
    "statement": "Large ridges or ledges greater than 50mm showed more positive results for biodiversity than smaller ones.",
    "citations": [
      "3465"
    ]
  },
  {
    "statement": "One study reported that large ridges or ledges, when combined with grooves and small protrusions, increased combined macroalgae, microalgae, and invertebrate species diversity.",
    "citations": [
      "3465"
    ]
  },
  {
    "statement": "When grooves and small ridges/ledges are created together, some studies found this increased species diversity and/or richness.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "When grooves and small ridges/ledges are created together, some studies found mixed effects on species diversity and/or richness depending on factors like depth, shore level, and site.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "The effects of linear depressions and elevations on population abundance were mixed.",
    "citations": [
      "3473",
      "3464",
      "3465",
      "3474"
    ]
  },
  {
    "statement": "Some studies showed increased population abundances due to linear depressions and elevations, while others showed no effect or mixed results.",
    "citations": [
      "3473",
      "3464",
      "3465",
      "3474"
    ]
  },
  {
    "statement": "The effect of linear depressions and elevations on population abundance can depend on the specific organisms and environmental conditions.",
    "citations": [
      "3473",
      "3464",
      "3465",
      "3474"
    ]
  }
]

[
  {
    "statement": "Using shell-concrete or quarried rock in place of standard-concrete alters the combined macroalgae and invertebrate community composition on structure surfaces.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "Using ECOncrete™ in place of standard-concrete or fibreglass alters the combined macroalgae and invertebrate community composition on structure surfaces.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "Creating texture, grooves, holes, pits and/or small ledges in addition to using environmentally-sensitive materials alters the combined macroalgae and invertebrate community composition on structure surfaces.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "ECOncrete™ surfaces with added habitats support mobile invertebrate, non-mobile invertebrate and/or fish species that are absent from standard-concrete or fibreglass structure surfaces.",
    "citations": []
  },
  {
    "statement": "Creating hole habitats on subtidal artificial structures alters the combined macroalgae and invertebrate or mobile invertebrate and fish community composition on and around the structures.",
    "citations": [
      "3434"
    ]
  },
  {
    "statement": "Creating hole habitats on subtidal artificial structures also supports mobile invertebrate, non-mobile invertebrate and/or fish species that are absent from structure surfaces without added habitat features.",
    "citations": []
  },
  {
    "statement": "Long flexible habitats created on subtidal artificial structures support macroalgae and non-mobile invertebrate or fish species that are absent from structure surfaces without flexible habitats.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "Groove habitats and small ledges created on a subtidal artificial structure, along with holes and environmentally-sensitive material, alter the combined macroalgae and invertebrate community composition.",
    "citations": [
      "3452"
    ]
  },
  {
    "statement": "Groove habitats and small ledges created on a subtidal artificial structure, along with holes and environmentally-sensitive material, support non-mobile invertebrate species that are absent from structure surfaces without added habitat features.",
    "citations": [
      "3452"
    ]
  },
  {
    "statement": "Creating textured surfaces is a less consistently effective intervention for altering community composition.",
    "citations": []
  },
  {
    "statement": "Creating groove habitats alone is a less consistently effective intervention for altering community composition.",
    "citations": []
  },
  {
    "statement": "Creating pit habitats is a less consistently effective intervention for altering community composition.",
    "citations": []
  },
  {
    "statement": "Creating short flexible habitats is a less consistently effective intervention for altering community composition.",
    "citations": []
  },
  {
    "statement": "Harvesting restrictions show effects on fish community composition but have limited evidence.",
    "citations": []
  },
  {
    "statement": "Ceasing or altering maintenance activities show minimal effects on community composition.",
    "citations": [
      "3447"
    ]
  }
]

[
  {
    "statement": "Several habitat modifications on intertidal artificial structures in Australia have shown mixed or neutral results for fish abundance.",
    "citations": []
  },
  {
    "statement": "Creating short flexible habitats (1-50 mm) showed neutral results for fish abundance.",
    "citations": [
      "3459"
    ]
  },
  {
    "statement": "One study found that creating short flexible habitats did not increase fish abundance on and around structure surfaces during high tide.",
    "citations": [
      "3459"
    ]
  },
  {
    "statement": "Creating rock pools demonstrated mixed effects on fish abundance.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "One Australian study on creating rock pools found mixed effects on fish abundance depending on the species group and site.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "Transplanting or seeding organisms onto structures showed neutral results for fish abundance.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "Two Australian studies found that transplanting oysters and/or coralline algae did not increase fish abundance on and around structure surfaces.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "Creating grooves and small protrusions/ridges/ledges (1-50 mm) showed neutral results for fish abundance.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "Three Australian studies found that creating grooves and small protrusions/ridges/ledges did not increase combined fish or juvenile salmon abundances on and around structure surfaces.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "Creating small ridges or ledges (1-50 mm) showed neutral results for fish abundance.",
    "citations": [
      "3464"
    ]
  },
  {
    "statement": "One Australian study found that small ledges supported similar fish abundance to grooves created in between the ledges.",
    "citations": [
      "3464"
    ]
  }
]

[
  {
