    ]
  },
  {
    "statement": "Pit habitats created on a subtidal artificial structure supported fish species that were absent from structure surfaces without the added habitat features.",
    "citations": [
      "3455"
    ]
  },
  {
    "statement": "The effects of pit habitats on fish abundances varied depending on the species group.",
    "citations": [
      "3455"
    ]
  }
