[
  {
    "statement": "Multiple conservation actions for artificial structures have been studied in Australian estuaries.",
    "citations": []
  },
  {
    "statement": "The conservation actions studied in Australian estuaries focused on habitat enhancement and organism transplantation approaches.",
    "citations": []
  },
  {
    "statement": "Creating long flexible habitats on subtidal artificial structures has been examined in three studies in southeast Australian estuaries.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "Long flexible habitats on subtidal artificial structures supported macroalgae and non-mobile invertebrate or fish species that were absent from structure surfaces without flexible habitats.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "The long flexible habitats were found to be used by seahorses.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "Long flexible habitats had mixed effects on fish species richness and abundance around structures, depending on fish presence when the habitats were created.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "Creating hole habitats on intertidal artificial structures was studied in three Australian estuarine sites.",
    "citations": [
      "3467"
    ]
  },
  {
    "statement": "Hole habitats supported macroalgae and non-mobile invertebrate species absent from structure surfaces without added habitat features.",
    "citations": [
      "3467"
    ]
  },
  {
    "statement": "Hole habitats on intertidal artificial structures increased combined macroalgae and invertebrate species diversity and richness.",
    "citations": [
      "3467"
    ]
  },
  {
    "statement": "Hole habitats were observed being used by sea slugs, urchins and octopuses.",
    "citations": [
      "3467"
    ]
  },
  {
    "statement": "Hole habitats had mixed effects on limpet abundance depending on shore level and site.",
    "citations": [
      "3467"
    ]
  },
  {
    "statement": "Creating groove habitats on intertidal artificial structures has been extensively studied with seven studies conducted in southeast Australian estuaries.",
    "citations": [
      "3473"
    ]
  },
