    "citations": [
      "3461"
    ]
  },
  {
    "statement": "Reducing the slope of intertidal artificial structures did not increase macroalgal, oyster or mobile invertebrate abundance.",
    "citations": [
      "3461"
    ]
  },
  {
    "statement": "Transplanting organisms onto subtidal artificial structures was studied in one Australian estuarine site.",
    "citations": [
      "3471"
    ]
  },
  {
    "statement": "Transplanting sea urchins onto subtidal artificial structures reduced the cover of non-native sea mat on kelps growing on the structure.",
    "citations": [
      "3471"
    ]
  }
]

[
  {
    "statement": "Creating linear habitat features such as grooves, ridges or ledges on intertidal artificial structures produces varied effects on biodiversity.",
    "citations": []
  },
  {
    "statement": "Creating groove habitats and small ridges or ledges can alter the combined community composition of macroalgae and invertebrates.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "The effects of groove habitats and small ridges or ledges on community composition depend on site-specific factors, the presence of water-retaining and light-shading covers, and the size and arrangement of the features.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "Linear features like grooves, ridges, and ledges support species that are absent from artificial structure surfaces that lack these features.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "Creating groove habitats and small ridges or ledges on structure surfaces has been found to increase the combined species diversity and/or richness of macroalgae and invertebrates.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "The effects of grooves and ridges on species richness and diversity vary depending on the depth or height of the features, the shore level, the species group, and the site.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "Grooves on artificial structures support higher species richness than small ridges or ledges created between the grooves.",
    "citations": [
      "3473"
    ]
  },
  {
    "statement": "Species diversity in grooves versus ridges varies depending on the depth of the groove.",
    "citations": [
      "3473"
    ]
  },
  {
    "statement": "The responses of population abundance to the creation of linear habitat features were mixed across studies.",
    "citations": []
  },
  {
    "statement": "Creating groove habitats and small ridges or ledges did not always increase the combined abundance of macroalgae and invertebrates.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "The abundance of macroalgae and invertebrates increased when linear features were partially-covered with water-retaining and light-shading covers.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "The abundance of macroalgae and invertebrates increased when linear features were combined with large ledges.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "The creation of linear habitat features had mixed effects on the abundances of mobile invertebrates, non-mobile invertebrates, limpets, mussels, juvenile oysters, and barnacles.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "The effects of linear habitat features on invertebrate abundances depended on the feature's depth or height, the presence of large ledges or covers, the shore level, and the site.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "Creating groove habitats and small ridges or ledges generally does not increase fish species richness or abundance.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "Behavioral effects of creating linear features on intertidal artificial structures included increased feeding activity for juvenile salmon.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "Behavioral effects of creating linear features on intertidal artificial structures included an increased amount of time that benthic fishes spent interacting with structure surfaces.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "Large ridges or ledges greater than 50 mm in size led to an increased abundance of mussels and limpets, but not barnacles.",
    "citations": [
      "3465"
    ]
  },
  {
    "statement": "Large ridges or ledges greater than 50 mm in size led to increased rockweed abundance.",
    "citations": [
      "3465"
    ]
  },
  {
    "statement": "Groove habitats on intertidal artificial structures were found to be colonized by microalgal species.",
    "citations": [
      "3474",
      "3473"
    ]
  },
  {
    "statement": "Groove habitats on intertidal artificial structures were used by mussels and periwinkles.",
    "citations": [
      "3474",
      "3473"
    ]
  },
  {
    "statement": "The effectiveness of linear habitat features appears to depend heavily on design parameters including the size, arrangement, and depth of the features.",
    "citations": []
  },
  {
    "statement": "The effectiveness of linear habitat features appears to depend heavily on the presence of additional features or covers.",
    "citations": []
  }
]

[
  {
    "statement": "The most consistently effective habitat creation methods for increasing species richness on subtidal artificial structures are combinations of multiple small-scale features.",
    "citations": []
